from pathlib import Path
import json,gzip,hashlib,datetime,subprocess,sys
out=Path(__file__).resolve().parents[1];phase=sys.argv[1];sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();b=json.load(gzip.open(out/'before.json.gz'));scope=json.load(open(out/'scope.json'));hashes={p:sha(p) for p in list(b['hashes'])+scope['nuclei'] if Path(p).exists()};lib=Path('target/debug/libtypst_core.rlib');source=out/'field-control.rs';binary=out/(phase+'-field-control.bin');cmd=['rustc','--edition=2021',str(source),'--extern','typst_core='+str(lib),'-L','dependency=target/debug/deps','-o',str(binary)];begin=datetime.datetime.now(datetime.timezone.utc).isoformat();compile=subprocess.run(cmd,capture_output=True,text=True);assert compile.returncode==0,compile.stderr;run=subprocess.run([str(binary)],capture_output=True,text=True);binary.unlink();assert run.returncode==0;lines=run.stdout.splitlines();assert len(lines)==85;count=int(lines[-1].split('=')[1]);r=dict(start=begin,end=datetime.datetime.now(datetime.timezone.utc).isoformat(),head=b['head'],source_hashes=hashes,command=cmd,source_sha256=sha(source),rlib=dict(path=str(lib),sha256=sha(lib)),compile_stderr=compile.stderr,exit=run.returncode,stdout=run.stdout,stderr=run.stderr,controls=84,differences=count,sources_unchanged=all(sha(p)==h for p,h in hashes.items()));assert r['sources_unchanged'];(out/(phase+'-field-probe.json')).write_text(json.dumps(r,indent=2)+'\n');print('Field transparency:',count,'differences in 84 controls')
